hit(key) { const entry=pin(key); try { if(entry.mode!=="counter") throw WrongMode();
 let now=clock.nowMonotone();
 for(;;) { const i=now%300, round=Math.floor(now/300), word=entry.words[i].load();
  if(roundOf(word)>round) { now=clock.nowMonotone(); continue; }   // newer round: resample, never write back
  const next=roundOf(word)===round ? pack(round, checkedCount(countOf(word)+1)) : pack(round,1);
  if(entry.words[i].compareAndSet(word,next)) return;
  now=clock.nowMonotone(); } } finally { unpin(entry); } }
getHits(key) { const entry=pin(key); try { let snapshotTime=clock.nowMonotone(); const seen=[];
 for(let i=0;i<300;i++) { const w=entry.words[i].load(); seen.push(w);
  snapshotTime=Math.max(snapshotTime, roundOf(w)*300+i); }               // each word loaded once, no lock
 const inWindow=(w,i)=>{ const s=roundOf(w)*300+i; return s>snapshotTime-300 && s<=snapshotTime; };
 return {count:sumChecked(seen.filter(inWindow).map(countOf)), snapshotTime};
 } finally { unpin(entry); } }
tryAcquire(key,limit) { const entry=pin(key);                         // limiter-mode keys only
 return entry.admission.withLock(()=>{ const {count}=scan(entry);
  if(count>=limit) return {accepted:false,count};
  casIncrement(entry, clock.nowMonotone()); return {accepted:true,count:count+1}; }); }

hit(key,threadId) { const entry=pin(key); try { const s=entry.stripes[hash(threadId)%S];
 s.lock(); try { const now=clock.nowMonotone(); expire(s,now);
  if(!safe(s.total+1)) throw Overflow();
  if(s.tail?.second===now) s.tail.count++; else s.push({second:now,count:1}); s.total++;
 } finally { s.unlock(); } } finally { unpin(entry); } }
withAllStripes(entry,fn) { for(const s of entry.stripes) s.lock();          // ascending index order
 try { const now=clock.nowMonotone(); let total=0;
  for(const s of entry.stripes) { expire(s,now); total=checkedAdd(total,s.total); }
  return fn(now,total); } finally { for(const s of [...entry.stripes].reverse()) s.unlock(); } }
getHits(key) { return withAllStripes(pin(key),(now,total)=>({count:total,snapshotTime:now})); }
tryAcquire(key,threadId,limit) { const entry=pin(key); return withAllStripes(entry,(now,total)=>{
 if(total>=limit) return {accepted:false,count:total};
 append(entry.stripes[hash(threadId)%S],now); return {accepted:true,count:total+1}; }); }
